const publishedPaths = <LearningPath>[
  LearningPath(id: "dc01-dc02", number: "1.1", title: "Promote Primary & Secondary Domain Controller", subtitle: "DC01 + DC02 / Active Directory", category: "Network build", description: "Promote the primary and secondary domain controllers on Windows Server, place them on their own network segment, verify the domain's health, and keep a record of the build.", icon: "directory", published: true, studyTime: "5 guided chapters", topics: 5,
    materials: [
