      LearningResource(id: "dc-package", title: "Training materials · ZIP", publisher: "Secure By Design", description: "Offline guide, workbook (PDF and Word), and verification commands.", url: "https://securebydesigninc.com/training/dc01-dc02/SecureByDesign-DC01-DC02-Learning-Package.zip", category: "Training materials", icon: "directory")
