      LearningResource(id: "dns-configuration-guide", title: "Configure DNS · Interactive guide", publisher: "Secure By Design", description: "Service discovery, zones, records & troubleshooting", url: "https://securebydesigninc.com/training/dns-configuration", category: "Training materials", icon: "directory"),
